# ---------------- MUC 8 — SAI LAM ----------------
P(('h2','8. 5 sai lầm thường gặp khi thiết kế văn phòng 90m2'))
P(('p','Năm lỗi dưới đây gặp ở hầu hết phương án doanh nghiệp tự lên cho diện tích này. Điểm chung: hậu quả đều quy được ra số chỗ ngồi hoặc số tiền phải sửa lại.'))
P(('table',
   ['Sai lầm','Vì sao hay mắc','Cái giá phải trả'],
   [['1. Đặt phòng họp ở trong cùng','Muốn dành vị trí gần cửa cho lễ tân cho đẹp','Khách phải đi xuyên khu làm việc mỗi lượt. Với 15 – 18 người ngồi ở đó, mỗi lượt khách là một lần cả sàn mất tập trung'],
    ['2. Chia quá nhiều phòng kín vì "90m² rộng rồi"','Diện tích lớn hơn 70m² nên nghĩ thoải mái chia','Bốn phòng kín lấy đi 12 – 15m² cho riêng phần tường, vách và hành lang dẫn vào — tương đương mất 5 – 6 chỗ ngồi'],
    ['3. Đặt pantry cạnh khu làm việc','Chỗ đó gần ống nước sẵn, đỡ phải kéo đường cấp thoát','Mùi và tiếng máy pha lọt thẳng vào chỗ ngồi cả ngày. Sửa sau khi đã hoàn thiện thì phải đục lại sàn để dời đường nước'],
    ['4. Không quy hoạch điện, mạng từ đầu','Nghĩ rằng lắp sau cũng được','Phải đi dây nổi sau khi vào ở, hoặc đục lại sàn và vách vừa hoàn thiện — phát sinh cả chi phí lẫn thời gian ngừng làm việc'],
    ['5. Thiết kế vừa khít số người hiện tại','Ngân sách có hạn, chưa chắc năm sau tuyển thêm','Doanh nghiệp cỡ 15 người thường là doanh nghiệp đang lớn. Tăng 20% nhân sự là hết chỗ, phải cải tạo lại chỉ sau 1 – 2 năm']]))
P(('p','Cách phòng cho lỗi thứ năm, và cũng là điều 90m² làm được mà 70m² không: **chừa sẵn một dãy bàn trống**. Khi lên phương án, cộng thêm 15 – 20% số chỗ so với nhân sự hiện tại và chọn bàn mô-đun ghép nối được — phần dư đó dùng tạm làm bàn dự án hoặc bàn khách, không thành khoảng trống lãng phí.'))
P(('img','a70-09','Lối đi trong văn phòng cần tối thiểu 1,2m — bóp hẹp hơn là người ngồi trong phải đứng dậy nhường đường (Ảnh tham khảo)'))

# ---------------- MUC 9 — CHI PHI ----------------
P(('h2','9. Chi phí thiết kế và thi công văn phòng 90m2'))
P(('p','Đây là chỗ dễ hiểu nhầm nhất, và cũng là chỗ thông tin trên mạng lệch nhau nhiều nhất. Khảo sát các đơn vị đang công bố giá cho diện tích này cho thấy phí thiết kế được báo từ 115.000đ/m² tới 1.500.000đ/m² — **chênh nhau hơn 13 lần** cho cùng một dịch vụ. Mục này tách rõ hai khoản và nói thẳng cái gì làm giá chênh.'))

P(('h3','9.1. Phí thiết kế và chi phí thi công là hai khoản khác nhau'))
P(('table',
   ['Hạng mục','Đơn giá thị trường','Thành tiền cho 90m²'],
   [['Phí thiết kế','150.000 – 400.000 đ/m²','13,5 – 36 triệu'],
    ['Thi công gói cơ bản','2,5 – 4 triệu/m²','225 – 360 triệu'],
    ['Thi công gói tiêu chuẩn','4 – 7 triệu/m²','360 – 630 triệu'],
    ['Thi công gói cao cấp','trên 7 triệu/m²','trên 630 triệu']]))
P(('note','Gói cơ bản: sơn, sàn, trần, hệ điện cơ bản, nội thất rời phổ thông. Gói tiêu chuẩn: thêm vách kính, tủ âm tường, hệ chiếu sáng thiết kế riêng, nội thất đặt sản xuất. Gói cao cấp: vật liệu nhập khẩu, hệ thống thông minh, gia công đặc thù. Đây là khoảng giá tham khảo — báo giá thực tế phụ thuộc hiện trạng mặt bằng và yêu cầu riêng.'))
P(('p','Con số 13 – 36 triệu là **phí thiết kế**, tức tiền trả cho bản vẽ 2D, phối cảnh 3D và hồ sơ kỹ thuật. Nó không bao gồm một viên gạch nào. Chi phí thi công mới là khoản lớn, gấp khoảng 15 – 20 lần phí thiết kế. Nhiều bài viết ghi “chi phí thiết kế thi công 90m2 khoảng 30 triệu” — đó là đang lấy phí thiết kế gọi thành chi phí trọn gói.'))

P(('h3','9.2. Vì sao phí thiết kế giữa các đơn vị chênh nhau nhiều đến vậy'))
P(('ul',[
  '**Có đơn vị miễn phí thiết kế nếu ký luôn thi công.** Phí thiết kế khi đó đã tính vào giá thi công, không phải rẻ hơn thật.',
  '**Khác nhau ở khối lượng hồ sơ bàn giao.** Chỉ layout 2D và vài ảnh 3D là một giá; đủ hồ sơ kỹ thuật để tòa nhà thẩm duyệt, bản vẽ triển khai chi tiết từng món nội thất là giá khác.',
  '**Số vòng chỉnh sửa.** Gói rẻ thường giới hạn 1 – 2 vòng; sửa thêm tính tiền.',
  '**Có khảo sát hiện trạng hay không.** Thiết kế trên số liệu khách tự đo và thiết kế sau khi đo đạc tại chỗ là hai mức công khác hẳn nhau.']))
P(('p','Khi so báo giá, câu nên hỏi không phải “bao nhiêu một mét vuông” mà là **“với mức giá này tôi nhận được những bản vẽ nào, sửa được mấy vòng, có khảo sát tại chỗ không”**.'))

P(('h3','9.3. Tiết kiệm chi phí ở đâu mà văn phòng 90m2 vẫn chuyên nghiệp'))
P(('p','Nguyên tắc chung: **giữ tiền cho khu khách nhìn thấy, cắt ở khu nội bộ.** Ở 90m², khu khách nhìn thấy chỉ chiếm khoảng 20% diện tích — lễ tân, khu chờ và phòng họp. Đầu tư đúng mức vào 20% đó, phần còn lại dùng vật liệu phổ thông mà không ai nhận ra.'))
P(('ul',[
  '**Bỏ trần giật cấp nhiều lớp**, giữ trần phẳng hoặc để mộc — tiết kiệm 22 – 36 triệu cho 90m².',
  '**Dùng vách kính khung nhôm** thay vách thạch cao cách âm ở phòng giám đốc — rẻ hơn, nhanh hơn, lại giữ được chỗ ngồi.',
  '**Chọn nội thất mô-đun có sẵn** cho khu làm việc chung, chỉ đặt sản xuất riêng quầy lễ tân và bàn họp.',
  '**Doanh nghiệp thuê ngắn hạn dưới 3 năm** nên ưu tiên hạng mục tháo lắp mang đi được — bàn, tủ, vách di động — thay vì hạng mục xây cố định.']))

# ---------------- MUC 10 — VI SAO CHON ----------------
P(('h2','10. Vì sao chọn Crystal Design TPL cho văn phòng 90m2'))
P(('p','Crystal Design TPL (thương hiệu Deco Crystal) có **hơn 25 năm kinh nghiệm** thiết kế, sản xuất và thi công nội thất trọn gói tại Việt Nam và khu vực Đông Nam Á. Với mặt bằng 90m², ba điểm sau ảnh hưởng trực tiếp đến kết quả doanh nghiệp nhận được:'))
P(('ul',[
  '**Nhà xưởng sản xuất 6.000m².** Nội thất do chính công ty sản xuất nên chủ động được tiến độ và điều chỉnh kích thước theo đúng mặt bằng thực tế — quan trọng khi phải kê vừa 16 – 18 chỗ ngồi mà vẫn giữ đủ lối đi 1,2 – 1,4m.',
  '**Đội ngũ chuyên gia kết hợp Việt Nam – Hàn Quốc**, nâng cao tiêu chuẩn thiết kế và thi công so với mặt bằng chung.',
  '**Khảo sát và thiết kế 3D miễn phí.** Doanh nghiệp nhìn thấy phương án phân khu, luồng di chuyển và số chỗ ngồi thực tế trước khi quyết định ngân sách.']))
P(('img','a70-23','Khu vực lễ tân do Crystal Design TPL thiết kế và thi công — điểm dừng đầu tiên của luồng khách'))

# ---------------- MUC 11 — HOI DAP ----------------
P(('h2','11. Câu hỏi thường gặp khi thiết kế văn phòng 90m2'))

P(('h3','11.1. Văn phòng 90m2 ngồi được tối đa bao nhiêu người?'))
P(('p','Ở mức bố trí phổ biến là **15 – 18 chỗ**, vẫn giữ đủ lễ tân, phòng giám đốc, phòng họp và pantry. Nếu bỏ hết phòng kín và dùng bàn nhỏ, con số lên tới 20 – 26 chỗ nhưng văn phòng sẽ không còn chỗ tiếp khách riêng. Hình dạng mặt bằng cũng làm chênh khoảng 2 chỗ: theo ba sơ đồ ở mục 4, dạng vuông cho 17 chỗ, lô góc 16 chỗ, hẹp dài 15 chỗ.'))

P(('h3','11.2. Chi phí thiết kế thi công văn phòng 90m2 khoảng bao nhiêu?'))
P(('p','Cần tách làm hai khoản. **Phí thiết kế** theo giá thị trường là 150.000 – 400.000đ/m², tương đương 13,5 – 36 triệu cho 90m². **Chi phí thi công** là khoản lớn hơn nhiều: 225 – 360 triệu với gói cơ bản, 360 – 630 triệu với gói tiêu chuẩn. Con số vài chục triệu thường thấy trên mạng chỉ là phí thiết kế, không bao gồm thi công.'))

P(('h3','11.3. Thời gian thi công văn phòng 90m2 mất bao lâu?'))
P(('p','Khoảng **30 – 40 ngày** cho một văn phòng 90m² gói tiêu chuẩn, gồm: khảo sát 1 – 2 ngày · thiết kế và dựng 3D 8 – 12 ngày · hồ sơ kỹ thuật 3 – 5 ngày · sản xuất và thi công 16 – 22 ngày · nghiệm thu bàn giao 2 ngày. Đây là khoảng tham khảo theo tiến độ phổ biến của ngành; mốc chính xác phụ thuộc hiện trạng mặt bằng và số vòng duyệt bản vẽ.'))

P(('h3','11.4. Văn phòng 90m2 nên làm mấy phòng họp?'))
P(('p','Một phòng họp 8 chỗ là đủ cho doanh nghiệp 15 – 18 người. Nếu đội thường xuyên gọi điện hoặc họp trực tuyến, phương án tốt hơn là **một phòng họp 6 – 8 chỗ cộng một buồng gọi điện 2 – 3m²** — buồng này chiếm rất ít diện tích nhưng giải quyết đúng vấn đề tiếng ồn của không gian mở. Làm hai phòng họp kín trên 90m² thì mất 5 – 6 chỗ ngồi, thường không đáng.'))

P(('h3','11.5. Văn phòng 90m2 có nên thiết kế không gian mở không?'))
P(('p','Nên, nhưng mở có kiểm soát. Mở hoàn toàn khu làm việc cho thêm 3 – 4 chỗ ngồi so với phương án chia phòng, và dễ đổi bố cục khi nhân sự thay đổi. Tuy nhiên vẫn nên giữ ít nhất một phòng họp kín tiếng để tiếp khách, cộng trần tiêu âm phủ khu làm việc chung. Ở mật độ trên 15 người trong 90m², tiếng ồn là vấn đề có thật.'))

# ---------------- KET BAI ----------------
P(('p','Tóm lại, một mặt bằng 90m² chia được đủ năm khu chức năng và bố trí 15 – 18 chỗ ngồi ở mức phổ biến, trong đó riêng hình dạng mặt bằng đã làm con số chênh nhau khoảng 2 chỗ. Về ngân sách, phí thiết kế rơi vào 13,5 – 36 triệu, còn chi phí thi công là 225 – 630 triệu tùy gói vật liệu; toàn bộ quá trình từ khảo sát đến bàn giao mất khoảng 30 – 40 ngày. Điều đáng nhớ nhất là 90m² đã đủ rộng để không phải cắt bớt gì, nên thứ quyết định văn phòng chạy trơn hay không nằm ở chỗ khác: **thiết kế văn phòng 90m2** làm tốt là khi khách vào tới phòng họp mà không đi qua chỗ ngồi nào, và nhân viên đi lấy cà phê mà không ai phải ngẩng đầu lên. Crystal Design TPL khảo sát mặt bằng và dựng phương án 3D miễn phí, để doanh nghiệp thấy rõ hai luồng đi đó trên bản vẽ trước khi quyết định ngân sách.'))

P(('box_tacgia','Đặng Trường Minh — Giám đốc Thiết kế, Crystal Design TPL','Hơn 25 năm trong ngành thiết kế và thi công nội thất văn phòng. Trực tiếp phụ trách các phương án bố trí mặt bằng cho doanh nghiệp vừa và nhỏ tại Hà Nội và TP.HCM.'))

